import java.util.Scanner;
public class FahrenheitToCelsius {
	public static void main(String[] args) {
		//Khatwa 1: Ta'reef al-bayanat allati nahtajuha li-hadha al-barnamaj
		final int BASE = 32;
		final double CONVERSION_FACTOR = 5.0 / 9;
		//Khatwa 2: Qira'at qimat al-Fahrenheit al-mudkhalah
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil qimat al-Fahrenheit: ");
		int fahrenheitTemp = scan.nextInt();
		scan.close();
		//Khatwa 3: Hisaab al-muival bil-Celsius li-qimat al-Fahrenheit
		double celsiusTemp = (fahrenheitTemp - BASE) * CONVERSION_FACTOR ;
		System.out.println("Hararat al-Fahrenheit: " + fahrenheitTemp);
		System.out.println("Maadil bil-Celsius: " + celsiusTemp);
	}
}
